('ar-p02','ar','passage','reading','في الحديقة','x6_park',array['a4','a5']::text[],'القراءة وفهم المقروء',$j${"text": "ذهبت سلمى إلى الحديقة. لعبت بالكرة مع أخيها. ثم أكلا تفاحة حمراء.", "vocab": [["الحديقة", "مكان فيه أشجار وأزهار نلعب فيه"]], "qs": [{"q": "إلى أين ذهبت سلمى؟", "o": ["الحديقة", "المدرسة", "السوق"], "a": 0}, {"q": "ماذا أكلت سلمى وأخوها؟", "o": ["تفاحة", "موزة", "خبزا"], "a": 0}, {"q": "مع من لعبت سلمى؟", "o": ["أخيها", "جدتها", "معلمتها"], "a": 0}]}$j$::jsonb,'كُتب المحتوى برمجيًا بصياغة أصلية وفُحصت بنيته آليًا (الإجابات الصحيحة والخيارات والأحرف)، وراجعت زاد التهجئة والمعنى للفئة العمرية. لم يراجعه معلم لغة متخصص بعد.',true,'published',71),
('ar-p03','ar','passage','reading','أحمد والعصفور','1f426',array['a5','a6','g1','g2']::text[],'القراءة وفهم المقروء',$j${"text": "وجد أحمد عصفورا صغيرا تحت الشجرة. كان العصفور حزينا لأنه لا يستطيع الطيران. وضع أحمد العصفور في علبة صغيرة، وأعطاه الماء والحب. بعد أيام طار العصفور عاليا في السماء.", "vocab": [["حزينا", "غير سعيد"], ["عاليا", "بعيدا إلى فوق"]], "qs": [{"q": "أين وجد أحمد العصفور؟", "o": ["تحت الشجرة", "في البيت", "في السيارة"], "a": 0}, {"q": "لماذا كان العصفور حزينا؟", "o": ["لا يستطيع الطيران", "لا يحب الماء", "ضاع منه الحب"], "a": 0}, {"q": "ماذا فعل العصفور في النهاية؟", "o": ["طار في السماء", "نام", "سبح في الماء"], "a": 0}], "events": ["وجد أحمد العصفور", "أعطى أحمد العصفور الماء والحب", "طار العصفور في السماء"]}$j$::jsonb,'كُتب المحتوى برمجيًا بصياغة أصلية وفُحصت بنيته آليًا (الإجابات الصحيحة والخيارات والأحرف)، وراجعت زاد التهجئة والمعنى للفئة العمرية. لم يراجعه معلم لغة متخصص بعد.',true,'published',72),
('ar-p04','ar','passage','reading','يوم المطر','1f327',array['a5','a6','g1','g2']::text[],'القراءة وفهم المقروء',$j${"text": "في يوم ممطر لبست ليلى معطفها الأصفر وأخذت مظلتها. مشت مع أمها إلى المدرسة. رأت ليلى الأطفال يقفزون في الماء فابتسمت.", "vocab": [["ممطر", "تنزل فيه الأمطار"], ["مظلة", "أداة تحمينا من المطر"], ["معطف", "لباس نلبسه فوق الثياب في الجو البارد"]], "qs": [{"q": "ماذا لبست ليلى؟", "o": ["معطفا أصفر", "قبعة حمراء", "حذاء أبيض"], "a": 0}, {"q": "ماذا أخذت ليلى معها؟", "o": ["مظلة", "كرة", "كتابا"], "a": 0}, {"q": "إلى أين مشت ليلى؟", "o": ["المدرسة", "الحديقة", "السوق"], "a": 0}]}$j$::jsonb,'كُتب المحتوى برمجيًا بصياغة أصلية وفُحصت بنيته آليًا (الإجابات الصحيحة والخيارات والأحرف)، وراجعت زاد التهجئة والمعنى للفئة العمرية. لم يراجعه معلم لغة متخصص بعد.',true,'published',73),
('ar-p05','ar','passage','reading','النملة النشيطة','1f41d',array['a5','a6','g1','g2']::text[],'القراءة وفهم المقروء',$j${"text": "تعمل النملة طوال الصيف. تجمع الطعام وتحمله إلى بيتها تحت الأرض. وعندما يأتي الشتاء تأكل النملة من طعامها وتبقى دافئة وسعيدة.", "vocab": [["تجمع", "تضع الأشياء في مكان واحد"], ["دافئة", "غير باردة"]], "qs": [{"q": "متى تعمل النملة؟", "o": ["طوال الصيف", "في الشتاء فقط", "في الليل فقط"], "a": 0}, {"q": "أين بيت النملة؟", "o": ["تحت الأرض", "فوق الشجرة", "في الماء"], "a": 0}, {"q": "لماذا النملة سعيدة في الشتاء؟", "o": ["عندها طعام", "عندها كرة", "عندها كتاب"], "a": 0}], "events": ["جمعت النملة الطعام في الصيف", "جاء الشتاء", "أكلت النملة من طعامها"]}$j$::jsonb,'كُتب المحتوى برمجيًا بصياغة أصلية وفُحصت بنيته آليًا (الإجابات الصحيحة والخيارات والأحرف)، وراجعت زاد التهجئة والمعنى للفئة العمرية. لم يراجعه معلم لغة متخصص بعد.',true,'published',74),
('ar-p06','ar','passage','reading','رحلة إلى البحر','x6_sea',array['g3','g4']::text[],'القراءة وفهم المقروء',$j${"text": "خرجت أسرة سعيد في رحلة إلى البحر يوم الجمعة. بنى سعيد وأخته قصرا من الرمل، وجمعت الأم أصدافا جميلة. وفي المساء جلست الأسرة على الشاطئ تأكل العشاء وتشاهد غروب الشمس. عادوا إلى البيت متعبين لكنهم فرحوا كثيرا.", "vocab": [["الشاطئ", "الأرض الرملية بجانب البحر"], ["أصداف", "أغطية صلبة جميلة تعيش فيها كائنات بحرية"], ["غروب", "نزول الشمس في آخر النهار"]], "qs": [{"q": "متى كانت الرحلة؟", "o": ["يوم الجمعة", "يوم السبت", "في الشتاء"], "a": 0}, {"q": "ماذا بنى سعيد وأخته؟", "o": ["قصرا من الرمل", "بيتا من الخشب", "قاربا"], "a": 0}, {"q": "ماذا جمعت الأم؟", "o": ["أصدافا", "أوراقا", "حجارة كبيرة"], "a": 0}, {"q": "ماذا فعلت الأسرة في المساء؟", "o": ["أكلت العشاء وشاهدت الغروب", "ذهبت إلى السوق", "لعبت كرة القدم"], "a": 0}], "events": ["ذهبت الأسرة إلى البحر", "بنى سعيد قصرا من الرمل", "أكلت الأسرة العشاء على الشاطئ", "عادت الأسرة إلى البيت"]}$j$::jsonb,'كُتب المحتوى برمجيًا بصياغة أصلية وفُحصت بنيته آليًا (الإجابات الصحيحة والخيارات والأحرف)، وراجعت زاد التهجئة والمعنى للفئة العمرية. لم يراجعه معلم لغة متخصص بعد.',true,'published',75),
('ar-p07','ar','passage','reading','بذرة صغيرة','1f331',array['g3','g4']::text[],'القراءة وفهم المقروء',$j${"text": "زرعت هدى بذرة صغيرة في أصيص. كانت تسقيها كل يوم وتضعها قرب النافذة. بعد أسبوع خرجت ورقتان خضراوان من التراب. فرحت هدى كثيرا وعرفت أن الصبر والاهتمام يجعلان النبتة تكبر.", "vocab": [["أصيص", "وعاء صغير نزرع فيه النبات"], ["الصبر", "الانتظار بهدوء دون ملل"]], "qs": [{"q": "أين زرعت هدى البذرة؟", "o": ["في أصيص", "في البحر", "في الصحن"], "a": 0}, {"q": "ماذا كانت تفعل هدى كل يوم؟", "o": ["تسقي البذرة", "تقطف الزهرة", "تنقلها من مكانها"], "a": 0}, {"q": "ماذا خرج بعد أسبوع؟", "o": ["ورقتان خضراوان", "زهرة حمراء", "ثمرة كبيرة"], "a": 0}], "events": ["زرعت هدى البذرة", "سقتها كل يوم", "خرجت الورقتان الخضراوان"]}$j$::jsonb,'كُتب المحتوى برمجيًا بصياغة أصلية وفُحصت بنيته آليًا (الإجابات الصحيحة والخيارات والأحرف)، وراجعت زاد التهجئة والمعنى للفئة العمرية. لم يراجعه معلم لغة متخصص بعد.',true,'published',76),
('ar-p08','ar','passage','reading','المكتبة الجديدة','1f4da',array['g3','g4']::text[],'القراءة وفهم المقروء',$j${"text": "افتتحت مدرسة رامي مكتبة جديدة. فيها رفوف ملونة وكتب كثيرة للقصص والعلوم. وقال المعلم إن كل طالب يستطيع أن يستعير كتابا لمدة أسبوع. اختار رامي كتابا عن الفضاء وقرر أن يعيده في الموعد المحدد.", "vocab": [["رفوف", "ألواح توضع عليها الكتب"], ["يستعير", "يأخذ الشيء ليعيده بعد مدة"], ["الموعد المحدد", "الوقت المتفق عليه"]], "qs": [{"q": "ماذا افتتحت المدرسة؟", "o": ["مكتبة جديدة", "ملعبا جديدا", "مطعما"], "a": 0}, {"q": "كم مدة استعارة الكتاب؟", "o": ["أسبوع", "يوم واحد", "شهر"], "a": 0}, {"q": "عن ماذا كان كتاب رامي؟", "o": ["الفضاء", "الحيوانات", "الطبخ"], "a": 0}]}$j$::jsonb,'كُتب المحتوى برمجيًا بصياغة أصلية وفُحصت بنيته آليًا (الإجابات الصحيحة والخيارات والأحرف)، وراجعت زاد التهجئة والمعنى للفئة العمرية. لم يراجعه معلم لغة متخصص بعد.',true,'published',77),
